run("Minimum edit count precedes maximum matching support in positive-cost search",[]{
    // Independent exhaustive enumeration for short concrete sequences. Score only
    // overlaps meeting the minimum; minimize edits, then maximize actual matches.
    std::mt19937 rng(2520);for(unsigned trial=0;trial<100;++trial){std::string a,b;for(unsigned i=0;i<5;++i){a.push_back("ACGT"[rng()%4]);b.push_back("ACGT"[rng()%4]);}
        unsigned bestEdits=3,bestMatches=0;
        std::function<void(unsigned,unsigned,unsigned,unsigned)> visit=[&](unsigned i,unsigned j,unsigned edits,unsigned matches){if(edits>2)return;if(i==a.size()||j==b.size()){if(matches>=3&&(edits<bestEdits||(edits==bestEdits&&matches>bestMatches))){bestEdits=edits;bestMatches=matches;}return;}visit(i+1,j+1,edits+(a[i]!=b[j]),matches+(a[i]==b[j]));visit(i+1,j,edits+1,matches);visit(i,j+1,edits+1,matches);};
        for(unsigned i=0;i<a.size();++i)visit(i,0,0,0);for(unsigned j=1;j<b.size();++j)visit(0,j,0,0);
        Document d;d.load({{"a",a},{"b",b}});auto settings=exact(3);settings.maximumEdits=2;const auto p=plan_sequence_merge(d,{1,2},settings);
        if(!p.ids.empty())need(p.editsUsed==bestEdits&&p.overlappingPositions-p.residueConflicts==bestMatches,"Returned overlap agrees with independently enumerated priority");
        if(bestEdits==3)need(p.ids.empty(),"No eligible exhaustive overlap means no result");
    }
});
