    Document d;d.load({{"a",a},{"b",b}});auto settings=exact(55);settings.maximumEdits=2;need(plan_sequence_merge(d,{1,2},settings).ids.empty(),"Two search differences insufficient");settings.maximumEdits=3;
    const auto p=plan_sequence_merge(d,{1,2},settings);need(p.ids.size()==2&&p.editsUsed==3&&p.substitutionsUsed==3&&p.indelBasesUsed==0&&p.compatibleDifferencesUsed==1&&p.residueConflicts==2,"Exact search-event breakdown distinguishes compatible IUPAC from conflicts");
